INSERT OR REPLACE INTO entries (id, type, owner_id, visibility, data, search_text, created_at, updated_at) VALUES ('verb:stare', 'verb', 'system', 'public', '{"lemma":"stare","nl":"blijven (ook: zich voelen)","regularity":"irregolare","conjugationClass":"-are","auxiliary":"essere","note":"Onregelmatig (sto, stai, sta...). Hulpwerkwoord essere; het deelwoord ''stato'' is gelijk aan dat van essere, dus de passato prossimo (sono stato...) valt samen met die van essere. Betekent ''blijven'' en ook ''zich voelen/bevinden'' — Come stai? = ''Hoe gaat het?''.","forms":{"presente":{"io":{"it":"sto","nl":"ik blijf"},"tu":{"it":"stai","nl":"jij blijft"},"lui_lei":{"it":"sta","nl":"hij/zij blijft"},"noi":{"it":"stiamo","nl":"wij blijven"},"voi":{"it":"state","nl":"jullie blijven"},"loro":{"it":"stanno","nl":"zij blijven"}},"passato_prossimo":{"io":{"it":"sono stato/stata","nl":"ik ben gebleven"},"tu":{"it":"sei stato/stata","nl":"jij bent gebleven"},"lui_lei":{"it":"è stato/stata","nl":"hij/zij is gebleven"},"noi":{"it":"siamo stati/state","nl":"wij zijn gebleven"},"voi":{"it":"siete stati/state","nl":"jullie zijn gebleven"},"loro":{"it":"sono stati/state","nl":"zij zijn gebleven"}},"imperfetto":{"io":{"it":"stavo","nl":"ik bleef"},"tu":{"it":"stavi","nl":"jij bleef"},"lui_lei":{"it":"stava","nl":"hij/zij bleef"},"noi":{"it":"stavamo","nl":"wij bleven"},"voi":{"it":"stavate","nl":"jullie bleven"},"loro":{"it":"stavano","nl":"zij bleven"}},"futuro_semplice":{"io":{"it":"starò","nl":"ik zal blijven"},"tu":{"it":"starai","nl":"jij zult blijven"},"lui_lei":{"it":"starà","nl":"hij/zij zal blijven"},"noi":{"it":"staremo","nl":"wij zullen blijven"},"voi":{"it":"starete","nl":"jullie zullen blijven"},"loro":{"it":"staranno","nl":"zij zullen blijven"}},"condizionale_presente":{"io":{"it":"starei","nl":"ik zou blijven"},"tu":{"it":"staresti","nl":"jij zou blijven"},"lui_lei":{"it":"starebbe","nl":"hij/zij zou blijven"},"noi":{"it":"staremmo","nl":"wij zouden blijven"},"voi":{"it":"stareste","nl":"jullie zouden blijven"},"loro":{"it":"starebbero","nl":"zij zouden blijven"}}}}', 'stare blijven (ook: zich voelen)', 1767225600000, 1767225600000);
